"use strict";function initializePdfButton(o){let e=o.find("a").first(),d=e.data("element-id"),i=e.data("post-id"),r=e.data("queried-id"),l=e.data("converter"),s=e.data("ajax-url"),c=e.data("ajax-action"),f=e.data("title"),u=e.data("preview")==="yes",m=e.data("new-tab")==="yes";if(l!=="html")return;const w=async function(){e.addClass("fetching-pdf");let t=new FormData;t.set("queried_id",r),t.set("post_id",i),t.set("element_id",d),t.set("action",c);try{let a=await fetch(s,{method:"POST",body:new URLSearchParams(t)});if(a.headers.get("Content-Type")!=="application/pdf"){const b=await a.json();console.error("PDF Button: "+b.data.message);return}let p=await a.blob(),n=document.createElement("a");n.href=window.URL.createObjectURL(p),u?m&&(n.target="_blank"):n.download=f,n.click()}catch(a){console.error("PDF Button: "+a.message)}finally{e.removeClass("fetching-pdf")}};e.on("click",()=>{w()})}jQuery(window).on("elementor/frontend/init",function(){elementorFrontend.isEditMode()||elementorFrontend.hooks.addAction("frontend/element_ready/dce_pdf_button.default",initializePdfButton)});
